 const BARE_SECONDS = /^\d+$/;
-const COMPONENTS = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
+const COMPONENTS = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i;

 export function parseDuration(text: string): number {
   if (BARE_SECONDS.test(text)) {
     return Number(text);
   }

   const match = COMPONENTS.exec(text);
   if (text === "" || match === null) {
     throw new Error(`Invalid duration: "${text}"`);
   }
